from itertools import combinations
n=8
edges=list(combinations(range(n),2))
idx={e:i for i,e in enumerate(edges)}
# backtrack with constraints check complete subsets when edge assigned
triples=list(combinations(range(n),3))
quads=list(combinations(range(n),4))
# incidence constraints as edge indices
tri_edges=[[idx[tuple(sorted((a,b)))] for a,b in combinations(t,2)] for t in triples]
quad_edges=[[idx[tuple(sorted((a,b)))] for a,b in combinations(q,2)] for q in quads]
# Try brute force maybe 2^28 268M too much. Backtrack ordered edges.
assign=[None]*len(edges)
# For faster constraints per edge
constraints_by_edge=[[] for _ in edges]
constraints=[]
# red triangle constraint: not all zero -> type 'red'
for es in tri_edges:
    ci=len(constraints); constraints.append((es,0));
    for e in es: constraints_by_edge[e].append(ci)
# blue K4: not all one -> type 'blue'
for es in quad_edges:
    ci=len(constraints); constraints.append((es,1));
    for e in es: constraints_by_edge[e].append(ci)

# dynamic choose next? simple order
nodes=0
sol=None

def ok_after(e):
    for ci in constraints_by_edge[e]:
        es,val=constraints[ci]
        all_assigned=True
        all_val=True
        for ee in es:
            a=assign[ee]
            if a is None:
                all_assigned=False
                break
            if a!=val:
                all_val=False
                break
        if all_assigned and all_val:
            return False
    return True

# add pruning: for constraints if all assigned among prefix? above enough. choose next variable with MRV? no.

def bt(pos=0):
    global nodes, sol
    nodes+=1
    if pos==len(edges):
        sol=assign.copy(); return True
    # order maybe symmetry break? edge 0,1 red? no
    e=pos
    for val in [0,1]:
        assign[e]=val
        if ok_after(e):
            if bt(pos+1): return True
        assign[e]=None
    return False

print('edges', edges)
print(bt(), nodes)
print(sol)
# Verify
def verify(sol):
    for t, es in zip(triples, tri_edges):
        if all(sol[e]==0 for e in es): return False, ('redtri',t,es)
    for q, es in zip(quads, quad_edges):
        if all(sol[e]==1 for e in es): return False, ('blueK4',q,es)
    return True,None
print(verify(sol))
# Print adjacency matrix red/blue
for i in range(n):
    row=[]
    for j in range(n):
        if i==j: row.append('.')
        else: row.append(str(sol[idx[tuple(sorted((i,j)))]]))
    print(' '.join(row))
